def flag_existing_core_teams(apps, schema_editor):
    Team = apps.get_model('base', 'Team')
    flagged_organizers = set()
    candidates = Team.objects.filter(name__in=CORE_TEAM_NAMES).order_by('organizer_id', 'pk')
    for team in candidates.iterator():
        # Each organizer has at most one core team; keep the oldest matching team if there are several.
        if team.organizer_id in flagged_organizers:
            continue
        flagged_organizers.add(team.organizer_id)
        team.is_core_team = True
        team.save(update_fields=['is_core_team'])


def unflag_all_core_teams(apps, schema_editor):
    Team = apps.get_model('base', 'Team')
    Team.objects.filter(is_core_team=True).update(is_core_team=False)


